-- questions
INSERT INTO questions
  (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation,
   is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code)
VALUES
  ('55555555-0601-0000-0000-000000000001', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Ce matin, nous ___ le bus pour aller au travail. »',
   'Le passé composé du verbe « prendre » avec le sujet « nous » se forme avec l’auxiliaire « avoir » au présent + le participe passé « pris » : « nous avons pris ». « Prenons » est le présent, « sommes pris » est une forme passive ou incorrecte ici, et « avons prendre » mélange l’auxiliaire avec l’infinitif.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_passe_compose_avoir'),

  ('55555555-0601-0000-0000-000000000002', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Elle est arrivée ___ huit heures. »',
   'Pour indiquer une heure précise, on utilise la préposition « à » : « à huit heures ». « En » indique souvent une durée ou un pays féminin, « dans » indique un moment futur, et « depuis » exprime une durée commencée dans le passé.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_preposition_heure'),

  ('55555555-0601-0000-0000-000000000003', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Je voudrais ___ eau, s’il vous plaît. »',
   'Devant un nom féminin singulier qui commence par une voyelle, l’article partitif devient « de l’ » : « de l’eau ». « Du » s’emploie avec un masculin singulier, « de la » devant un féminin commençant par une consonne, et « des » au pluriel.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_article_partitif_voyelle'),

  ('55555555-0601-0000-0000-000000000004', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Remplacez « à Marie » par un pronom : « Je téléphone à Marie. » → « Je ___ téléphone. »',
   '« Téléphoner à quelqu’un » se construit avec un complément indirect. Pour une personne au singulier, on utilise « lui » : « Je lui téléphone ». « La » et « le » sont des COD, et « y » remplace plutôt un lieu ou une chose introduite par « à ».',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_pronom_coi_lui'),

  ('55555555-0601-0000-0000-000000000005', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Nous allons ___ au restaurant ce soir. »',
   'Le futur proche se forme avec « aller » au présent + infinitif. Après « nous allons », il faut l’infinitif « manger ». « Mangeons » est le présent, « mangé » est un participe passé, et « mangerons » est un futur simple.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_futur_proche_infinitif'),

  ('55555555-0601-0000-0000-000000000006', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Il y a ___ monde dans le métro ce matin. »',
   'L’expression correcte est « beaucoup de » devant un nom : « beaucoup de monde ». « Beaucoup » seul ne suffit pas devant un nom, « beaucoup du » est incorrect ici, et « très » s’emploie surtout devant un adjectif ou un adverbe.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_quantite_beaucoup_de'),

  ('55555555-0601-0000-0000-000000000007', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Quand j’étais enfant, je ___ souvent chez ma grand-mère. »',
   'Pour décrire une habitude dans le passé, on utilise l’imparfait : « j’allais ». « Je suis allé » indique plutôt une action ponctuelle terminée, « je vais » est le présent, et « j’irai » est le futur.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_imparfait_habitude'),

  ('55555555-0601-0000-0000-000000000008', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Cette voiture est ___ chère que l’autre. »',
   'Le comparatif d’infériorité avec un adjectif se forme avec « moins ... que » : « moins chère que ». « Aussi ... que » exprime l’égalité, « très » ne se combine pas avec « que », et « beaucoup » ne convient pas directement devant l’adjectif dans cette structure.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_comparatif_inferiorite'),

  ('55555555-0601-0000-0000-000000000009', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Je n’ai ___ vu ce film. »',
   'Pour dire qu’une action n’a pas eu lieu à un moment quelconque de la vie, on utilise « ne ... jamais » : « Je n’ai jamais vu ce film ». « Rien » nie une chose, « personne » nie une personne, et « plus » indique qu’une action ne continue plus.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_negation_jamais'),

  ('55555555-0601-0000-0000-000000000010', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Le livre ___ tu lis est très intéressant. »',
   'Le pronom relatif « que » remplace le COD du verbe « lire » : « tu lis le livre ». « Qui » serait sujet du verbe suivant, « où » indique un lieu ou un moment, et « dont » s’emploie avec « de ».',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_pronom_relatif_que'),

  ('55555555-0601-0000-0000-000000000011', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « La personne ___ parle est ma voisine. »',
   'Le pronom relatif « qui » est sujet du verbe « parle » : « la personne parle ». « Que » remplace un COD, « où » un lieu ou moment, et « dont » un complément introduit par « de ».',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_pronom_relatif_qui'),

  ('55555555-0601-0000-0000-000000000012', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Je vais ___ docteur demain matin. »',
   'On dit « aller chez le docteur » pour parler d’une personne ou d’un professionnel. « À le » se contracte normalement en « au », mais « au docteur » n’est pas naturel ici. « Dans » indique un espace intérieur, et « en » ne convient pas.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_preposition_chez_professionnel'),

  ('55555555-0601-0000-0000-000000000013', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Vous devez ___ votre carte d’identité. »',
   'Après « devoir », le verbe principal se met à l’infinitif : « vous devez présenter ». « Présentez » est l’impératif ou le présent, « présenté » est le participe passé, et « présente » est une forme conjuguée.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_devoir_infinitif'),

  ('55555555-0601-0000-0000-000000000014', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Je cherche mes lunettes, mais je ne les trouve ___ . »',
   'Dans une phrase négative simple, « ne ... pas » encadre le verbe conjugué : « je ne les trouve pas ». « Rien » nierait une chose non précisée, « jamais » un moment, et « personne » une personne.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_negation_pas_pronom'),

  ('55555555-0601-0000-0000-000000000015', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Ils sont partis ___ vacances en juillet. »',
   'L’expression correcte est « partir en vacances ». « Aux vacances » n’est pas naturel dans cette phrase, « à vacances » est incorrect, et « dans vacances » ne convient pas.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_expression_en_vacances'),

  ('55555555-0601-0000-0000-000000000016', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Ma sœur est ___ que moi. Elle a 20 ans et j’ai 25 ans. »',
   'La sœur a moins d’années que le locuteur, donc elle est « plus jeune ». « Plus vieille » ou « plus âgée » indiqueraient l’inverse. « Aussi jeune » exprimerait une égalité.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_comparatif_age'),

  ('55555555-0601-0000-0000-000000000017', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Si tu viens demain, nous ___ ensemble. »',
   'Avec « si » + présent pour une condition réelle, la conséquence peut être au futur simple : « nous déjeunerons ». « Déjeunions » est l’imparfait, « avons déjeuné » le passé composé, et « déjeuner » est l’infinitif.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_condition_si_present_futur'),

  ('55555555-0601-0000-0000-000000000018', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Elle a acheté une robe ___ pour la fête. »',
   '« Robe » est féminin singulier, donc l’adjectif doit être au féminin singulier : « rouge ». Ici, la forme « rouge » ne change pas entre masculin et féminin, mais elle reste singulière. « Rouges » est pluriel, « roux » et « rousse » concernent surtout les cheveux ou une personne.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_accord_adjectif_couleur'),

  ('55555555-0601-0000-0000-000000000019', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Donne-moi ___ adresse, s’il te plaît. »',
   '« Adresse » est féminin singulier et commence par une voyelle. L’adjectif possessif devient « ton » devant une voyelle pour faciliter la prononciation : « ton adresse ». « Ta adresse » est incorrect, « votre » change de personne, et « tes » est pluriel.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_possessif_voyelle'),

  ('55555555-0601-0000-0000-000000000020', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Je suis allé à la poste ___ envoyer un colis. »',
   'Pour exprimer le but, on utilise « pour » + infinitif : « pour envoyer un colis ». « Parce que » introduit une cause avec une phrase, « mais » oppose deux idées, et « donc » exprime une conséquence.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_but_pour_infinitif'),

  ('55555555-0601-0000-0000-000000000021', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Nous avons rendez-vous ___ lundi prochain. »',
   'Pour un jour précis, on utilise généralement le jour seul : « lundi prochain ». « Le lundi » indique une habitude, « à lundi » est une formule de salutation, et « en lundi » est incorrect.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_jour_precis'),

  ('55555555-0601-0000-0000-000000000022', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Je ___ lève à sept heures tous les matins. »',
   'Le verbe pronominal « se lever » se conjugue avec un pronom réfléchi. Avec « je », on utilise « me » : « je me lève ». « Te » correspond à « tu », « se » à il/elle/on ou ils/elles, et « nous » à nous.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_verbe_pronominal_present'),

  ('55555555-0601-0000-0000-000000000023', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Vous avez déjà visité Marseille ? — Oui, nous ___ sommes allés l’année dernière. »',
   'Le pronom « y » remplace un lieu introduit par « à » ou une destination : « à Marseille » → « nous y sommes allés ». « En » remplace souvent « de + lieu » ou une quantité, « la » est COD féminin, et « lui » est COI pour une personne.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_pronom_y_lieu'),

  ('55555555-0601-0000-0000-000000000024', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Tu veux du café ? — Non merci, je n’___ veux pas. »',
   'Le pronom « en » remplace une quantité introduite par « de/du/de la/des » : « du café » → « je n’en veux pas ». « Le » désignerait un objet précis, « y » un lieu ou une chose introduite par « à », et « lui » une personne.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_pronom_en_quantite'),

  ('55555555-0601-0000-0000-000000000025', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Il faut ___ la porte avant de sortir. »',
   'Après l’expression impersonnelle « il faut », le verbe se met à l’infinitif : « fermer ». « Fermez » est impératif ou présent avec « vous », « fermé » est participe passé, et « ferme » est une forme conjuguée.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_il_faut_infinitif'),

  ('55555555-0601-0000-0000-000000000026', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Excusez-moi, ___ est la gare, s’il vous plaît ? »',
   'Pour demander un lieu, on utilise « où » : « Où est la gare ? ». « Quand » interroge le temps, « combien » la quantité ou le prix, et « pourquoi » la cause.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_interrogatif_ou'),

  ('55555555-0601-0000-0000-000000000027', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Je suis fatigué ___ j’ai beaucoup travaillé. »',
   '« Parce que » introduit la cause : la personne est fatiguée à cause du travail. « Donc » exprime la conséquence, « mais » l’opposition, et « ou » le choix.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_connecteur_cause'),

  ('55555555-0601-0000-0000-000000000028', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Nous sommes ___ en France depuis deux ans. »',
   'Avec le verbe « être » au passé composé et un sujet masculin pluriel ou mixte, le participe passé prend un -s : « arrivés ». « Arrivé » est masculin singulier, « arrivée » féminin singulier, et « arriver » est l’infinitif.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_accord_participe_etre'),

  ('55555555-0601-0000-0000-000000000029', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Cette valise est trop lourde, je ne peux pas ___ porter. »',
   '« Cette valise » est un COD féminin singulier. Le pronom correct est « la » : « je ne peux pas la porter ». « Le » est masculin, « lui » est COI pour une personne, et « en » remplace une quantité ou un complément introduit par « de ».',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_pronom_cod_la'),

  ('55555555-0601-0000-0000-000000000030', 'TCF', '22222222-0000-0000-0000-000000000003', NULL, NULL, 'A2', 'STRUCTURE',
   'Complétez : « Pendant les vacances, nous avons visité ___ musées. »',
   'Devant un nom pluriel avec une quantité non précisée, on utilise l’article indéfini « des » : « des musées ». « Du » est masculin singulier, « de la » féminin singulier, et « un » singulier.',
   'true', '2026-06-01 15:00:00+02', '2026-06-01 15:00:00+02', 'ACTIVE', NULL, NULL, 'struct_article_indefini_pluriel');

